/// A legal relation as reported by WSDP.
///
/// Legacy name-only relations retain `code = None`; no code is inferred from `name`.
#[derive(Clone, Debug, Eq, PartialEq)]
pub struct LegalRelation {
    /// Typed NTR code or raw unknown code; absent for legacy name-only relations.
    pub code: Option<LegalRelationCode>,
    /// Relation text supplied by the report.
    pub name: String,
}

impl LegalRelation {
    /// Returns ownership classification from the code metadata, if available.
    ///
    /// Name-only and unknown-coded relations return `None`; names are never classified.
    pub fn is_ownership(&self) -> Option<bool> {
        self.code.as_ref().and_then(LegalRelationCode::is_ownership)
    }
}

/// A legal-relation type returned directly by `seznamTypuPravnichVztahu`.
#[derive(Clone, Debug, Eq, PartialEq)]
pub struct LegalRelationType {
    /// Typed known code or an untouched unknown server code.
    pub code: LegalRelationCode,
    /// Server-supplied relation name.
    pub name: String,
    /// Server-supplied WSDP `vlastnictvi` value, independent of bundled metadata.
    pub is_ownership: bool,
}

/// A raw `TROJVAZBA` (three-way-link) registry code.
///
/// The single-letter names preserve the registry vocabulary without assigning
/// semantics that the registry does not define.
#[derive(Clone, Debug, Eq, Hash, PartialEq)]
#[non_exhaustive]
pub enum ThreeWayLinkCode {
    /// Registry code `M`.
    M,
    /// Registry code `O`.
    O,
    /// Registry code `U`.
    U,
    /// An unrecognized code, retained without changing its lexical representation.
    Other(String),
}

impl ThreeWayLinkCode {
    /// Parses a known code or preserves an unrecognized value in [`Self::Other`].
    pub fn new(raw: impl Into<String>) -> Self {
        let raw = raw.into();
        match raw.as_str() {
            "M" => Self::M,
            "O" => Self::O,
            "U" => Self::U,
            _ => Self::Other(raw),
        }
    }

    /// Returns the known or untouched unrecognized registry code.
    pub fn as_str(&self) -> &str {
        match self {
            Self::M => "M",
            Self::O => "O",
            Self::U => "U",
            Self::Other(raw) => raw,
        }
    }
}

impl fmt::Display for ThreeWayLinkCode {
    fn fmt(&self, formatter: &mut fmt::Formatter<'_>) -> fmt::Result {
        formatter.write_str(self.as_str())
    }
}

impl FromStr for ThreeWayLinkCode {
    type Err = Infallible;

    fn from_str(raw: &str) -> Result<Self, Self::Err> {
        Ok(Self::new(raw))
    }
}

/// A legal-relation registry section (`SEKCE`).
///
/// The `A1` through `A9` variants represent the raw registry values `1` through `9`.
#[derive(Clone, Debug, Eq, Hash, PartialEq)]
#[non_exhaustive]
pub enum LegalRelationSection {
    /// Section B (raw code `B`).
    B,
    /// Section C (raw code `C`).
    C,
    /// Section D (raw code `D`).
    D,
    /// Section A1 (raw code `1`).
    A1,
    /// Section A2 (raw code `2`).
    A2,
    /// Section A3 (raw code `3`).
    A3,
    /// Section A4 (raw code `4`).
    A4,
    /// Section A5 (raw code `5`).
    A5,
    /// Section A6 (raw code `6`).
    A6,
    /// Section A7 (raw code `7`).
    A7,
    /// Section A8 (raw code `8`).
    A8,
    /// Section A9 (raw code `9`).
    A9,
    /// An unrecognized section, retained without changing its lexical representation.
    Other(String),
}

impl LegalRelationSection {
    /// Parses a known section or preserves an unrecognized value in [`Self::Other`].
    pub fn new(raw: impl Into<String>) -> Self {
        let raw = raw.into();
        match raw.as_str() {
            "B" => Self::B,
            "C" => Self::C,
            "D" => Self::D,
            "1" => Self::A1,
            "2" => Self::A2,
            "3" => Self::A3,
            "4" => Self::A4,
            "5" => Self::A5,
            "6" => Self::A6,
            "7" => Self::A7,
            "8" => Self::A8,
            "9" => Self::A9,
            _ => Self::Other(raw),
        }
    }

    /// Returns the known raw `SEKCE` value or the untouched unrecognized value.
    pub fn as_str(&self) -> &str {
        match self {
            Self::B => "B",
            Self::C => "C",
            Self::D => "D",
            Self::A1 => "1",
            Self::A2 => "2",
            Self::A3 => "3",
            Self::A4 => "4",
            Self::A5 => "5",
            Self::A6 => "6",
            Self::A7 => "7",
            Self::A8 => "8",
            Self::A9 => "9",
            Self::Other(raw) => raw,
        }
    }
}

impl fmt::Display for LegalRelationSection {
    fn fmt(&self, formatter: &mut fmt::Formatter<'_>) -> fmt::Result {
        formatter.write_str(self.as_str())
    }
}

impl FromStr for LegalRelationSection {
    type Err = Infallible;

    fn from_str(raw: &str) -> Result<Self, Self::Err> {
        Ok(Self::new(raw))
    }
}

/// Complete pinned metadata for one `SC_T_PRAVNICH_VZT` row.
#[derive(Clone, Debug, Eq, PartialEq)]
pub struct LegalRelationMetadata {
    /// Official legal-relation code (`KOD`).
    pub code: LegalRelationCode,
    /// Referenced proceeding subject matter (`TPR_KOD`).
    pub proceeding_subject_matter: ProceedingSubjectMatterCode,
    /// Exact official Czech name (`NAZEV`).
    pub name: &'static str,
    /// Ownership classification (`VLASTNICTVI`).
    pub is_ownership: bool,
    /// Whether the relation benefits a subject (`PRO_OS`).
    pub benefits_subject: bool,
    /// Whether the relation benefits a property (`PRO_NEMOVITOST`).
    pub benefits_property: bool,
    /// Whether the relation burdens a subject (`K_OS`).
    pub burdens_subject: bool,
    /// Whether the relation burdens a property (`K_NEMOVITOSTI`).
    pub burdens_property: bool,
    /// First validity date (`PLATNOST_OD`).
    pub valid_from: Date,
    /// Last validity date, if any (`PLATNOST_DO`).
    pub valid_to: Option<Date>,
    /// Nationwide-scope flag (`CELOSTATNI_PUSOBNOST`).
    pub nationwide_scope: bool,
    /// Optional raw three-way-link code (`TROJVAZBA`).
    pub three_way_link: Option<ThreeWayLinkCode>,
    /// Optional registry section (`SEKCE`).
    pub section: Option<LegalRelationSection>,
    /// Joint-marital-property flag (`SJM`).
    pub joint_marital_property: bool,
    /// Superior-legal-person flag (`PRO_NADRIZENOU_PO`).
    pub superior_legal_person: bool,
    /// Optional creditor-share flag (`PODIL_VERITELE`).
    pub creditor_share: Option<bool>,
    /// Parent-relation requirement (`POVINNOST_R_JPV`).
    pub requires_parent_relation: bool,
    /// Building-right flag (`PRAVO_STAVBY`).
    pub building_right: bool,
    /// Optional ordering flag (`PORADI`).
    pub ordering: Option<bool>,
    /// Optional accessory-co-ownership restriction (`PRSV_OMEZENI_PRAV`).
    pub accessory_co_ownership_restriction: Option<bool>,
    /// Optional accessory-co-ownership dependent-relation flag (`PRSV_ZAVISLE_JPV`).
    pub accessory_co_ownership_dependent_relation: Option<bool>,
}

/// Complete pinned metadata for one `SC_T_PREDMETU_R` row.
#[derive(Clone, Debug, Eq, PartialEq)]
pub struct ProceedingSubjectMatterMetadata {
    /// Official proceeding-subject-matter code (`KOD`).
    pub code: ProceedingSubjectMatterCode,
    /// Exact official Czech name (`NAZEV`).
    pub name: &'static str,
    /// First validity date (`PLATNOST_OD`).
    pub valid_from: Date,
    /// Last validity date, if any (`PLATNOST_DO`).
    pub valid_to: Option<Date>,
    /// Optional official description (`POPIS`); blank values remain absent.
    pub description: Option<&'static str>,
}

