#[cfg(test)]
mod tests {
    use std::collections::BTreeSet;

    use super::*;

    #[test]
    fn generated_mappings_cover_every_unique_registry_row() {
        assert_eq!(LEGAL_RELATION_METADATA.len(), 317);
        assert_eq!(PROCEEDING_SUBJECT_MATTER_METADATA.len(), 96);

        let legal_codes: BTreeSet<_> = LEGAL_RELATION_METADATA
            .iter()
            .map(|metadata| metadata.code.as_str())
            .collect();
        let proceeding_codes: BTreeSet<_> = PROCEEDING_SUBJECT_MATTER_METADATA
            .iter()
            .map(|metadata| metadata.code.as_str())
            .collect();
        assert_eq!(legal_codes.len(), 317);
        assert_eq!(proceeding_codes.len(), 96);
        assert!(legal_codes.contains("320"));
    }

    #[test]
    fn known_and_unknown_codes_roundtrip_lexically() {
        for expected in &LEGAL_RELATION_METADATA {
            let raw = expected.code.as_str();
            let code = LegalRelationCode::new(raw);
            assert_eq!(code, expected.code);
            assert_eq!(code.as_str(), raw);
            assert_eq!(code.to_string(), raw);
            assert_eq!(raw.parse::<LegalRelationCode>().unwrap(), code);
            assert!(std::ptr::eq(code.metadata().unwrap(), expected));
        }
        for expected in &PROCEEDING_SUBJECT_MATTER_METADATA {
            let raw = expected.code.as_str();
            let code = ProceedingSubjectMatterCode::new(raw);
            assert_eq!(code, expected.code);
            assert_eq!(code.as_str(), raw);
            assert_eq!(code.to_string(), raw);
            assert_eq!(raw.parse::<ProceedingSubjectMatterCode>().unwrap(), code);
            assert!(std::ptr::eq(code.metadata().unwrap(), expected));
        }

        for raw in ["", "030", " 30", "future-code", "320 "] {
            let code = LegalRelationCode::new(raw);
            assert_eq!(code, LegalRelationCode::Other(raw.to_owned()));
            assert_eq!(code.as_str(), raw);
            assert_eq!(code.to_string(), raw);
            assert!(code.metadata().is_none());
        }
        let code = ProceedingSubjectMatterCode::new("039");
        assert_eq!(code, ProceedingSubjectMatterCode::Other("039".to_owned()));
        assert_eq!(code.as_str(), "039");
        assert!(code.metadata().is_none());
    }

    #[test]
    fn ownership_classification_uses_metadata_not_variant_or_name() {
        assert_eq!(LegalRelationCode::new("30"), LegalRelationCode::Ownership);
        for raw in ["30", "115", "143", "221"] {
            assert_eq!(LegalRelationCode::new(raw).is_ownership(), Some(true));
        }
        assert_eq!(
            LegalRelationCode::ContractualMortgage.is_ownership(),
            Some(false)
        );
        assert_eq!(LegalRelationCode::new("32").is_ownership(), Some(false));
        assert_eq!(
            LegalRelationCode::Other("999".to_owned()).is_ownership(),
            None
        );

        let unknown = LegalRelation {
            code: Some(LegalRelationCode::Other("999".to_owned())),
            name: "Vlastnické právo".to_owned(),
        };
        assert_eq!(unknown.is_ownership(), None);
        let legacy = LegalRelation {
            code: None,
            name: "Vlastnické právo".to_owned(),
        };
        assert_eq!(legacy.is_ownership(), None);

        let runtime = LegalRelationType {
            code: LegalRelationCode::Other("future".to_owned()),
            name: "Future server relation".to_owned(),
            is_ownership: true,
        };
        assert!(runtime.is_ownership);
        assert!(runtime.code.metadata().is_none());
    }

    #[test]
    fn duplicate_names_keep_distinct_code_identity() {
        for (first, second) in [("85", "180"), ("86", "181"), ("196", "307")] {
            let first = LegalRelationCode::new(first);
            let second = LegalRelationCode::new(second);
            assert_ne!(first, second);
            assert_eq!(
                first.metadata().unwrap().name,
                second.metadata().unwrap().name
            );
        }
        assert_eq!(
            LegalRelationCode::new("85"),
            LegalRelationCode::ZahajenyPozemkoveUpravyCode85
        );
        assert_eq!(
            LegalRelationCode::new("180"),
            LegalRelationCode::ZahajenyPozemkoveUpravyCode180
        );

        let old = ProceedingSubjectMatterCode::new("14");
        let current = ProceedingSubjectMatterCode::new("82");
        assert_ne!(old, current);
        assert_eq!(old.metadata().unwrap().name, "Právo stavby");
        assert_eq!(
            old.metadata().unwrap().name,
            current.metadata().unwrap().name
        );
    }

    #[test]
    fn current_code_320_and_historical_validity_are_retained() {
        let code = LegalRelationCode::ChangeOfPreemptionRight;
        let metadata = code.metadata().unwrap();
        assert_eq!(code.as_str(), "320");
        assert_eq!(metadata.name, "Změna předkupního práva");
        assert_eq!(metadata.valid_from, Date::constant(2026, 11, 18));
        assert_eq!(metadata.valid_to, None);
        assert_eq!(metadata.three_way_link, Some(ThreeWayLinkCode::O));

        let historical = LegalRelationCode::new("1");
        let historical = historical.metadata().unwrap();
        assert_eq!(historical.valid_to, Some(Date::constant(1999, 12, 31)));
    }

    #[test]
    fn every_proceeding_reference_resolves() {
        for relation in &LEGAL_RELATION_METADATA {
            let proceeding = relation
                .proceeding_subject_matter
                .metadata()
                .unwrap_or_else(|| panic!("unresolved TPR_KOD for {}", relation.code));
            assert_eq!(
                proceeding.code.as_str(),
                relation.proceeding_subject_matter.as_str()
            );
        }
    }

    #[test]
    fn blank_registry_options_stay_absent() {
        let first = LegalRelationCode::new("1");
        let first = first.metadata().unwrap();
        assert_eq!(first.three_way_link, None);
        assert_eq!(first.creditor_share, None);
        assert_eq!(first.ordering, None);
        assert_eq!(first.accessory_co_ownership_restriction, None);
        assert_eq!(first.accessory_co_ownership_dependent_relation, None);
        assert_eq!(first.section, Some(LegalRelationSection::C));

        let blank_section = LegalRelationCode::new("116");
        let blank_section = blank_section.metadata().unwrap();
        assert_eq!(blank_section.section, None);
        assert_eq!(blank_section.valid_to, None);

        let populated = LegalRelationCode::new("221");
        let populated = populated.metadata().unwrap();
        assert_eq!(populated.section, Some(LegalRelationSection::A1));
        assert_eq!(populated.creditor_share, Some(false));
        assert_eq!(populated.accessory_co_ownership_restriction, Some(true));

        let proceeding = ProceedingSubjectMatterCode::new("1");
        let proceeding = proceeding.metadata().unwrap();
        assert_eq!(proceeding.valid_to, None);
        assert_eq!(proceeding.description, None);
        let described = ProceedingSubjectMatterCode::new("68");
        assert_eq!(
            described.metadata().unwrap().description,
            Some("opravy podle opatření ČÚZK č.j.2055/2001-24 a další nutné opravy")
        );
    }

    #[test]
    fn metadata_code_enums_preserve_known_and_unknown_raw_values() {
        for raw in ["M", "O", "U", "", "m", "future"] {
            let code = ThreeWayLinkCode::new(raw);
            assert_eq!(code.as_str(), raw);
            assert_eq!(code.to_string(), raw);
            assert_eq!(raw.parse::<ThreeWayLinkCode>().unwrap(), code);
        }
        for raw in [
            "B", "C", "D", "1", "2", "3", "4", "5", "6", "7", "8", "9", "", "A1", "future",
        ] {
            let section = LegalRelationSection::new(raw);
            assert_eq!(section.as_str(), raw);
            assert_eq!(section.to_string(), raw);
            assert_eq!(raw.parse::<LegalRelationSection>().unwrap(), section);
        }
        assert_eq!(LegalRelationSection::new("1"), LegalRelationSection::A1);
        assert_eq!(
            ThreeWayLinkCode::new("future"),
            ThreeWayLinkCode::Other("future".to_owned())
        );
    }
}
